"use strict";

const $ = (s) => document.querySelector(s);
const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
const fmt = (x, n = 2) => Number(x).toFixed(n);
const rng = (() => { let s = 20260917; return () => ((s = Math.imul(48271, s) % 2147483647) & 2147483647) / 2147483647; })();
const normal = () => Math.sqrt(-2 * Math.log(Math.max(rng(), 1e-9))) * Math.cos(2 * Math.PI * rng());

function chart(canvas, series, options = {}) {
  const ctx = canvas.getContext("2d"), w = canvas.width, h = canvas.height;
  ctx.clearRect(0, 0, w, h); ctx.fillStyle = "#0a1220"; ctx.fillRect(0, 0, w, h);
  const pad = { l: 48, r: 18, t: 18, b: 32 }, flat = series.flatMap(s => s.data);
  const min = options.min ?? Math.min(...flat, 0), max = options.max ?? Math.max(...flat, 1), range = max - min || 1;
  ctx.strokeStyle = "#23324b"; ctx.lineWidth = 1; ctx.fillStyle = "#75849e"; ctx.font = "11px Consolas";
  for (let i = 0; i <= 4; i++) { const y = pad.t + (h - pad.t - pad.b) * i / 4; ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(w - pad.r, y); ctx.stroke(); const v = max - range * i / 4; ctx.fillText(options.percent ? `${fmt(v,0)}%` : fmt(v, options.decimals ?? 1), 4, y + 4); }
  series.forEach(s => { if (s.data.length < 2) return; ctx.beginPath(); ctx.strokeStyle = s.color; ctx.lineWidth = s.width || 3; ctx.setLineDash(s.dash || []); s.data.forEach((v, i) => { const x = pad.l + (w - pad.l - pad.r) * i / Math.max(1, s.data.length - 1), y = pad.t + (max - v) / range * (h - pad.t - pad.b); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }); ctx.stroke(); ctx.setLineDash([]); });
}
function animateChart(canvas, series, options = {}) {
  let points = 2;
  const total = Math.max(...series.map(s => s.data.length));
  const draw = () => {
    chart(canvas, series.map(s => ({...s, data:s.data.slice(0, points)})), options);
    points += Math.max(2, Math.ceil(total / 45));
    if (points <= total + 2) requestAnimationFrame(draw);
  };
  draw();
}
function barChart(canvas, labels, values) {
  const ctx=canvas.getContext("2d"),w=canvas.width,h=canvas.height,pad={l:34,r:14,t:18,b:48},max=Math.max(1,...values),slot=(w-pad.l-pad.r)/Math.max(1,values.length);
  ctx.clearRect(0,0,w,h);ctx.fillStyle="#0a1220";ctx.fillRect(0,0,w,h);ctx.font="12px Consolas";ctx.textAlign="center";
  values.forEach((v,i)=>{const bh=(h-pad.t-pad.b)*v/max,x=pad.l+i*slot+slot*.16,y=h-pad.b-bh,bw=slot*.68;ctx.fillStyle=i%2?"#4f7cff":"#62e4ff";ctx.fillRect(x,y,bw,bh);ctx.fillStyle="#eef3ff";ctx.fillText(String(v),x+bw/2,Math.max(14,y-7));ctx.fillStyle="#9aa8c2";ctx.fillText(labels[i],x+bw/2,h-19)});
  ctx.textAlign="left";
}
function setConclusion(id, text, tone = "") {
  const target = $(id);
  if (!target) return;
  target.textContent = text;
  target.className = tone;
}
function addAction(logId, text, limit = 7) {
  const log = $(logId);
  if (!log) return;
  const item = document.createElement("li");
  item.textContent = text;
  log.prepend(item);
  while (log.children.length > limit) log.lastElementChild.remove();
}

// Bandit
const bandit = { probs: [.18, .37, .62, .44], counts: [0,0,0,0], values: [0,0,0,0], alpha:[1,1,1,1], beta:[1,1,1,1], steps:0, reward:0, regret:0, rewards:[0], regrets:[0], last:-1, decision:"" };
function betaSample(a,b){ const x = -Math.log(Math.max(rng(),1e-9))/a, y=-Math.log(Math.max(rng(),1e-9))/b; return x/(x+y); }
function renderBanditInputs(){ const host=$("#armInputs"); host.innerHTML=""; bandit.probs.forEach((p,i)=>{const l=document.createElement("label");l.innerHTML=`A${i+1}<input type="number" min="0.01" max="0.99" step="0.01" value="${p}">`;l.querySelector("input").onchange=e=>{bandit.probs[i]=clamp(+e.target.value,.01,.99);renderBandit()};host.append(l)}); }
function chooseArm(){const mode=$("#banditStrategy").value;if(mode==="epsilon"){const explore=rng()<+$("#epsilon").value;bandit.decision=explore?"исследование":"использование";if(explore)return Math.floor(rng()*4);return bandit.values.indexOf(Math.max(...bandit.values));}if(mode==="ucb"){bandit.decision="UCB: оптимизм для редкого действия";if(bandit.counts.includes(0))return bandit.counts.indexOf(0);const scores=bandit.values.map((v,i)=>v+Math.sqrt(2*Math.log(bandit.steps+1)/bandit.counts[i]));return scores.indexOf(Math.max(...scores));}bandit.decision="Thompson: выбор по апостериорной выборке";const scores=bandit.alpha.map((a,i)=>betaSample(a,bandit.beta[i]));return scores.indexOf(Math.max(...scores));}
function banditStep(){const a=chooseArm(),before=bandit.values[a],r=rng()<bandit.probs[a]?1:0,regretStep=Math.max(...bandit.probs)-bandit.probs[a];bandit.last=a;bandit.steps++;bandit.reward+=r;bandit.regret+=regretStep;bandit.counts[a]++;bandit.values[a]+=(r-bandit.values[a])/bandit.counts[a];bandit.alpha[a]+=r;bandit.beta[a]+=1-r;bandit.rewards.push(bandit.reward/bandit.steps);bandit.regrets.push(bandit.regret);renderBandit();const result=r?"получена награда 1":"награда 0";const conclusion=`A${a+1}: ${result}; Q изменилось ${fmt(before,2)} → ${fmt(bandit.values[a],2)}. Режим: ${bandit.decision}.`;setConclusion("#banditInsight",conclusion,r?"good":"warn");addAction("#banditActionLog",`Шаг ${bandit.steps}. ${conclusion} Прирост regret: ${fmt(regretStep,2)}.`);}
function renderBandit(){const host=$("#machines");host.innerHTML="";const best=bandit.values.indexOf(Math.max(...bandit.values));bandit.probs.forEach((p,i)=>{const m=document.createElement("div");m.className=`machine ${bandit.steps&&i===best?"best":""} ${bandit.last===i?"active":""}`;m.innerHTML=`<span class="machine-top">ARM ${i+1}</span><div class="reel">${bandit.last===i?(bandit.rewards.at(-1)>bandit.rewards.at(-2)?"◆":"·"):"?"}</div><span class="lever"></span><b>${fmt(bandit.values[i],2)}</b><small>Q · ${bandit.counts[i]} выборов</small>`;host.append(m)});$("#banditSteps").textContent=bandit.steps;$("#banditReward").textContent=bandit.reward;$("#banditRegret").textContent=fmt(bandit.regret,1);$("#banditBest").textContent=bandit.steps?`A${best+1}`:"—";chart($("#banditChart"),[{data:bandit.rewards,color:"#62e4ff"},{data:bandit.regrets.map((x,i)=>i?x/i:0),color:"#ffbd59",dash:[7,6]}],{min:0,max:Math.max(1,...bandit.regrets.map((x,i)=>i?x/i:0))});}
function resetBandit(){Object.assign(bandit,{counts:[0,0,0,0],values:[0,0,0,0],alpha:[1,1,1,1],beta:[1,1,1,1],steps:0,reward:0,regret:0,rewards:[0],regrets:[0],last:-1,decision:""});$("#banditActionLog").innerHTML="";setConclusion("#banditInsight","Эксперимент сброшен. Выполните новое действие.");renderBandit();}

// Cross-Entropy Method: random start, several bones and configurable action spaces.
const CEM_ACTIONS=[
  {dr:-1,dc:0,name:"вверх",short:"↑"},{dr:1,dc:0,name:"вниз",short:"↓"},{dr:0,dc:-1,name:"влево",short:"←"},{dr:0,dc:1,name:"вправо",short:"→"},
  {dr:-1,dc:-1,name:"по диагонали вверх-влево",short:"↖"},{dr:-1,dc:1,name:"по диагонали вверх-вправо",short:"↗"},{dr:1,dc:-1,name:"по диагонали вниз-влево",short:"↙"},{dr:1,dc:1,name:"по диагонали вниз-вправо",short:"↘"},
  {dr:-2,dc:0,name:"прыжок вверх",short:"⇈"},{dr:2,dc:0,name:"прыжок вниз",short:"⇊"},{dr:0,dc:-2,name:"прыжок влево",short:"⇇"},{dr:0,dc:2,name:"прыжок вправо",short:"⇉"}
];
const cem={size:9,actionCount:8,boneCount:3,policy:null,iteration:0,history:[0],start:[0,0],dog:[0,0],bones:[],visibleBones:[],path:[],success:0,mean:0,threshold:0,length:0,collected:0,playing:false,bestEpisode:null,bestScore:-Infinity,actionUsage:[]};
function sameCell(a,b){return a[0]===b[0]&&a[1]===b[1]}
function randomCells(size,count){const cells=[];while(cells.length<count){const p=[Math.floor(rng()*size),Math.floor(rng()*size)];if(!cells.some(x=>sameCell(x,p)))cells.push(p)}return cells}
function initPolicy(){cem.size=+$("#gridSize").value;cem.actionCount=+$("#actionCount").value;cem.boneCount=+$("#boneCount").value;cem.policy=Array.from({length:cem.size*cem.size},()=>Array(cem.actionCount).fill(1/cem.actionCount));const cells=randomCells(cem.size,cem.boneCount+1);cem.start=cells[0];cem.dog=[...cem.start];cem.bones=cells.slice(1);cem.visibleBones=cem.bones.map(x=>[...x]);cem.iteration=0;cem.history=[0];cem.success=0;cem.mean=0;cem.threshold=0;cem.length=0;cem.path=[];cem.collected=0;cem.bestEpisode=null;cem.bestScore=-Infinity;cem.actionUsage=Array(cem.actionCount).fill(0);$("#cemActionLog").innerHTML="";setConclusion("#cemInsight",`Новая задача: старт (${cem.start.join(", ")}), костей ${cem.boneCount}, действий ${cem.actionCount}.`);renderGrid();renderCem();renderPolicy();renderActionCounts();}
function stateId(p){return p[0]*cem.size+p[1]}
function sampleAction(ps){let z=rng(),c=0;for(let i=0;i<ps.length;i++){c+=ps[i];if(z<=c)return i}return ps.length-1}
function movePoint(p,a){const d=CEM_ACTIONS[a];return[clamp(p[0]+d.dr,0,cem.size-1),clamp(p[1]+d.dc,0,cem.size-1)]}
function distance(a,b){return Math.max(Math.abs(a[0]-b[0]),Math.abs(a[1]-b[1]))}
function nearestDistance(p,bones){return bones.length?Math.min(...bones.map(b=>distance(p,b))):0}
function heuristicAction(p,bones){let best=0,bestDist=Infinity;for(let a=0;a<cem.actionCount;a++){const np=movePoint(p,a),d=nearestDistance(np,bones);if(d<bestDist&&!sameCell(np,p)){bestDist=d;best=a}}return best}
function episode(mode="sample"){let p=[...cem.start],remaining=cem.bones.map(x=>[...x]),states=[],actions=[],ret=0,path=[{pos:[...p],action:null,reward:0,collected:null}],collected=0,max=cem.size*cem.size+cem.boneCount*cem.size;for(let t=0;t<max;t++){const st=stateId(p);let a;if(mode==="heuristic")a=heuristicAction(p,remaining);else if(mode==="greedy")a=cem.policy[st].indexOf(Math.max(...cem.policy[st]));else a=rng()<.18?heuristicAction(p,remaining):sampleAction(cem.policy[st]);states.push(st);actions.push(a);const before=nearestDistance(p,remaining),np=movePoint(p,a),after=nearestDistance(np,remaining);let reward=+$("#stepPenalty").value;if(sameCell(np,p))reward-=.03;if(after<before)reward+=.01;p=np;let collectedBone=null;const hit=remaining.findIndex(b=>sameCell(b,p));if(hit>=0){collectedBone=remaining[hit];remaining.splice(hit,1);collected++;reward+=.25;if(!remaining.length)reward+=2}ret+=reward;path.push({pos:[...p],action:a,reward,collected:collectedBone});if(!remaining.length)return{states,actions,ret,len:t+1,success:1,collected,path}}return{states,actions,ret,len:max,success:0,collected,path}}
function trainCem(times=1){const before=cem.success;for(let z=0;z<times;z++){const n=+$("#sessions").value,sessions=Array.from({length:n},()=>episode("sample"));sessions.push(episode("heuristic"));const sorted=sessions.map(x=>x.ret).sort((a,b)=>a-b),threshold=sorted[Math.floor(sorted.length*(+$("#elite").value/100))],elite=sessions.filter(x=>x.ret>=threshold),counts=Array.from({length:cem.size*cem.size},()=>Array(cem.actionCount).fill(.25));elite.forEach(e=>e.states.forEach((s,i)=>counts[s][e.actions[i]]++));counts.forEach((c,s)=>{const sum=c.reduce((a,b)=>a+b,0);cem.policy[s]=c.map(x=>x/sum)});const candidate=sessions.reduce((best,e)=>(e.collected*100+e.ret>best.collected*100+best.ret?e:best),sessions[0]);const score=candidate.collected*100+candidate.ret;if(score>cem.bestScore){cem.bestScore=score;cem.bestEpisode=candidate}cem.iteration++;cem.success=sessions.reduce((a,e)=>a+e.success,0)/sessions.length;cem.mean=sessions.reduce((a,e)=>a+e.ret,0)/sessions.length;cem.threshold=threshold;cem.length=sessions.reduce((a,e)=>a+e.len,0)/sessions.length;cem.history.push(cem.success)}cem.actionUsage=Array(cem.actionCount).fill(0);if(cem.bestEpisode)cem.bestEpisode.actions.forEach(a=>cem.actionUsage[a]++);renderCem();renderPolicy();renderActionCounts();const delta=(cem.success-before)*100,found=cem.bestEpisode?`${cem.bestEpisode.collected}/${cem.boneCount} костей за ${cem.bestEpisode.len} ходов`:"траектория не найдена";const conclusion=`После ${times} итерац${times===1?"ии":"ий"}: полный сбор ${Math.round(cem.success*100)}% (${delta>=0?"+":""}${fmt(delta,0)} п.п.). Лучшая траектория: ${found}.`;setConclusion("#cemInsight",conclusion,cem.bestEpisode?.success?"good":"warn");addAction("#cemActionLog",`Обучение до итерации ${cem.iteration}: ${conclusion}`);}
function renderGrid(){const host=$("#dogGrid");host.style.gridTemplateColumns=`repeat(${cem.size},1fr)`;host.innerHTML="";for(let r=0;r<cem.size;r++)for(let c=0;c<cem.size;c++){const x=document.createElement("div"),p=[r,c],onPath=cem.path.some(q=>sameCell(q,p)),isDog=sameCell(cem.dog,p),isBone=cem.visibleBones.some(q=>sameCell(q,p)),just=cem.justCollected&&sameCell(cem.justCollected,p);x.className=`cell ${onPath?"path":""} ${isDog?"dog":""} ${isBone?"bone":""} ${just?"collected":""}`;x.textContent=isDog?"🐕":isBone?"🦴":"";host.append(x)}}
function renderCem(){$("#cemIteration").textContent=cem.iteration;$("#cemMean").textContent=fmt(cem.mean,2);$("#cemThreshold").textContent=cem.iteration?fmt(cem.threshold,2):"—";$("#cemLength").textContent=cem.iteration?fmt(cem.length,1):"—";$("#cemSuccess").textContent=`${Math.round(cem.success*100)}%`;$("#cemBones").textContent=cem.collected;$("#cemBonesTotal").textContent=cem.boneCount;$(".score-ring").style.setProperty("--progress",`${cem.success*100}%`);chart($("#cemChart"),[{data:cem.history.map(x=>x*100),color:"#b9f36b"}],{min:0,max:100,percent:true});$("#cemPlay").disabled=!cem.bestEpisode||cem.playing;}
function renderPolicy(){const host=$("#cemPolicyTable");host.style.gridTemplateColumns=`repeat(${cem.size},1fr)`;host.innerHTML="";for(let r=0;r<cem.size;r++)for(let c=0;c<cem.size;c++){const p=[r,c],cell=document.createElement("div"),a=cem.policy?cem.policy[stateId(p)].indexOf(Math.max(...cem.policy[stateId(p)])):0;cell.className=`policy-cell ${sameCell(p,cem.start)?"start":""} ${cem.bones.some(b=>sameCell(b,p))?"target":""}`;cell.textContent=sameCell(p,cem.start)?"🐕":cem.bones.some(b=>sameCell(b,p))?"🦴":CEM_ACTIONS[a].short;host.append(cell)}$("#cemActionLegend").textContent=CEM_ACTIONS.slice(0,cem.actionCount).map((a,i)=>`${i}: ${a.short} ${a.name}`).join(" · ");$("#cemPolicySummary").textContent=cem.bestEpisode?`Лучшая найденная траектория собрала ${cem.bestEpisode.collected} из ${cem.boneCount} костей за ${cem.bestEpisode.len} ходов. Возврат ${fmt(cem.bestEpisode.ret,2)}.`:"Выполните обучение. После первой итерации таблица покажет жадное действие в каждой клетке.";}
function renderActionCounts(){barChart($("#cemActionChart"),CEM_ACTIONS.slice(0,cem.actionCount).map(a=>a.short),cem.actionUsage)}
async function playCem(){if(cem.playing||!cem.bestEpisode)return;cem.playing=true;cem.collected=0;cem.dog=[...cem.start];cem.visibleBones=cem.bones.map(x=>[...x]);cem.path=[[...cem.start]];cem.justCollected=null;renderCem();renderGrid();for(let i=1;i<cem.bestEpisode.path.length;i++){const step=cem.bestEpisode.path[i],action=CEM_ACTIONS[step.action];cem.dog=[...step.pos];cem.path.push([...step.pos]);cem.justCollected=step.collected;cem.visibleBones=cem.visibleBones.filter(b=>!step.collected||!sameCell(b,step.collected));if(step.collected)cem.collected++;renderGrid();renderCem();const rewardText=`r=${fmt(step.reward,2)}`;setConclusion("#cemInsight",`Ход ${i}: ${action.name}, клетка (${step.pos.join(", ")}), ${rewardText}${step.collected?" — кость собрана":""}.`,step.collected?"good":"warn");addAction("#cemActionLog",`Ход ${i}: ${action.short} ${action.name}; ${rewardText}${step.collected?"; кость собрана":""}.`,120);await new Promise(r=>setTimeout(r,320));cem.justCollected=null}const complete=cem.collected===cem.boneCount;const conclusion=complete?`Все ${cem.boneCount} костей собраны за ${cem.bestEpisode.len} ходов. Начислена супернаграда +2.`:`Собрано ${cem.collected} из ${cem.boneCount} костей. Нужны дополнительные итерации обучения.`;setConclusion("#cemInsight",conclusion,complete?"good":"warn");addAction("#cemActionLog",conclusion,120);cem.playing=false;renderCem();}

// MOEX laboratories 3–4. The browser evaluates deterministic reference policies on a
// frozen public-data snapshot. Full neural-network training remains in the Python modules.
let moexData=null, tabularProtocol=[], tradeProtocol=[], marlProtocol=[];
const mean=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:0;
const std=a=>{const m=mean(a);return Math.sqrt(mean(a.map(x=>(x-m)**2)))||1e-9};
const returns=rows=>rows.slice(1).map((r,i)=>r.close/rows[i].close-1);
function metrics(curve){const rr=curve.slice(1).map((x,i)=>x/curve[i]-1),peak=[];let p=curve[0],dd=0;curve.forEach(x=>{p=Math.max(p,x);peak.push(p);dd=Math.max(dd,1-x/p)});return{ret:curve.at(-1)/curve[0]-1,sharpe:mean(rr)/std(rr)*Math.sqrt(252),drawdown:dd};}

// Laboratory 2: genuine tabular TD control on the same frozen MOEX series as Lab 3.
function ema(values,period){const out=[],k=2/(period+1);values.forEach((v,i)=>out.push(i?v*k+out[i-1]*(1-k):v));return out;}
function indicatorRows(rows){const c=rows.map(x=>x.close),v=rows.map(x=>x.volume||0),e12=ema(c,12),e26=ema(c,26);return rows.map((r,i)=>{const from=Math.max(0,i-19),w=c.slice(from,i+1),rw=[];for(let j=Math.max(1,i-19);j<=i;j++)rw.push(c[j]/c[j-1]-1);let gains=0,losses=0;for(let j=Math.max(1,i-13);j<=i;j++){const d=c[j]-c[j-1];d>=0?gains+=d:losses-=d}const rs=losses?gains/losses:99,rsi=100-100/(1+rs),sma=mean(w),sigma=std(w),atr=mean(rows.slice(from,i+1).map((x,j,a)=>j?Math.max(x.high-x.low,Math.abs(x.high-a[j-1].close),Math.abs(x.low-a[j-1].close)):x.high-x.low)),vw=v.slice(from,i+1);return{...r,ret1:i?c[i]/c[i-1]-1:0,mom5:i>=5?c[i]/c[i-5]-1:0,trend:(c[i]-sma)/(sigma+1e-9),vol:std(rw),rsi,macd:(e12[i]-e26[i])/(c[i]+1e-9),atr:atr/(c[i]+1e-9),boll:4*sigma/(sma+1e-9),volumeZ:(v[i]-mean(vw))/std(vw),drawdown:1-c[i]/Math.max(...w)};});}
function qbin(x,lo,hi){return x<lo?0:x>hi?2:1;}
function tdState(row,position,set){const parts=[qbin(row.trend,-.35,.35),qbin(row.mom5,-.02,.02),qbin(row.vol,.009,.02)];if(set!=="basic")parts.push(qbin(row.rsi,40,60),qbin(row.macd,-.006,.006),qbin(row.atr,.015,.035));if(set==="extended")parts.push(qbin(row.boll,.05,.12),qbin(row.volumeZ,-.7,.7),qbin(row.drawdown,.05,.14));return `${parts.join("")}|${position}`;}
function localRng(seed=20260920){let s=seed;return()=>((s=Math.imul(48271,s)%2147483647)&2147483647)/2147483647;}
function greedyAction(q,state){const values=q.get(state)||[0,0];return values[1]>values[0]?1:0;}
function tdLearn(rows,algo,set,alpha,gamma,fee){const data=indicatorRows(rows),train=data.filter(x=>x.date<"2024-01-01"),q=new Map(),rand=localRng(20260920+algo.length+set.length),get=s=>{if(!q.has(s))q.set(s,[0,0]);return q.get(s)};for(let epoch=0;epoch<70;epoch++){let position=0,state=tdState(train[20],position,set),action=rand()<.22?+(rand()>.5):greedyAction(q,state);for(let i=20;i<train.length-1;i++){const nextRet=train[i+1].close/train[i].close-1,reward=action*nextRet-Math.abs(action-position)*fee-.08*Math.max(0,-action*nextRet);const nextState=tdState(train[i+1],action,set),nextGreedy=greedyAction(q,nextState),nextAction=rand()<.22?+(rand()>.5):nextGreedy;let bootstrap;if(algo==="Q-learning")bootstrap=Math.max(...get(nextState));else if(algo==="SARSA")bootstrap=get(nextState)[nextAction];else{const eps=.22,g=nextGreedy;bootstrap=get(nextState).reduce((s,v,a)=>s+v*((a===g?1-eps:0)+eps/2),0)}const values=get(state);values[action]+=alpha*(reward+gamma*bootstrap-values[action]);position=action;state=nextState;action=nextAction;}}
  return{q,data};}
function tdEvaluate(model,algo,set,fee){const test=model.data.filter(x=>x.date.startsWith("2025-")),eq=[100000],bh=[100000],actions=[];let position=0,trades=0;for(let i=20;i<test.length-1;i++){const state=tdState(test[i],position,set),action=greedyAction(model.q,state),nextRet=test[i+1].close/test[i].close-1;if(action!==position){eq[eq.length-1]*=1-fee;trades++}eq.push(eq.at(-1)*(1+action*nextRet));bh.push(bh.at(-1)*(1+nextRet));actions.push({date:test[i].date,action:action?"LONG":"CASH",state,equity:eq.at(-1),nextReturn:nextRet,rsi:test[i].rsi,macd:test[i].macd,vol:test[i].vol});position=action;}return{eq,bh,actions,trades,...metrics(eq),baseline:metrics(bh)};}
function tdExperiment(algo){const ticker=$("#tabularTicker").value,set=$("#indicatorSet").value,alpha=+$("#alpha").value,gamma=+$("#gamma").value,fee=+$("#tabularFee").value/100,rows=moexData.securities[ticker].candles;return tdEvaluate(tdLearn(rows,algo,set,alpha,gamma,fee),algo,set,fee);}
function runTabular(){if(!moexData)return setConclusion("#tabularInsight","Данные MOEX ещё загружаются.","warn");const algo=$("#tabularAlgo").value,result=tdExperiment(algo);tabularProtocol=result.actions;animateChart($("#tabularChart"),[{data:result.eq,color:"#62e4ff"},{data:result.bh,color:"#687893",dash:[7,6]}],{min:Math.min(...result.eq,...result.bh)*.98,max:Math.max(...result.eq,...result.bh)*1.02,decimals:0});$("#tabularEquity").textContent=new Intl.NumberFormat("ru-RU",{style:"currency",currency:"RUB",maximumFractionDigits:0}).format(result.eq.at(-1));$("#tabularReturn").textContent=`${result.ret>=0?"+":""}${fmt(result.ret*100,1)}%`;$("#tabularSharpe").textContent=fmt(result.sharpe,2);$("#tabularDrawdown").textContent=`−${fmt(result.drawdown*100,1)}%`;$("#tabularTrades").textContent=result.trades;$("#tabularAction").textContent=result.actions.at(-1)?.action||"READY";$("#tabularDate").textContent=`Test 2025 · ${result.actions.length} решений`;$("#tabularActionLog").innerHTML="";result.actions.filter((_,i)=>i%Math.max(1,Math.floor(result.actions.length/6))===0).slice(0,6).forEach(a=>addAction("#tabularActionLog",`${a.date}: ${a.action}; state=${a.state}; RSI=${fmt(a.rsi,1)}, MACD=${fmt(a.macd*100,2)}%, σ=${fmt(a.vol*100,2)}%, капитал ₽${fmt(a.equity,0)}.`));const algos=["Q-learning","SARSA","Expected SARSA"],all=algos.map(a=>[a,tdExperiment(a)]),best=[...all].sort((a,b)=>b[1].sharpe-a[1].sharpe)[0],bh=all[0][1].baseline;$("#tabularComparison").innerHTML=`<div class="table-scroll"><table><thead><tr><th>Алгоритм</th><th>Доходность</th><th>Sharpe</th><th>Max DD</th><th>Сделок</th></tr></thead><tbody>${all.map(([a,r])=>`<tr><td>${a}</td><td>${fmt(r.ret*100,1)}%</td><td>${fmt(r.sharpe,2)}</td><td>${fmt(r.drawdown*100,1)}%</td><td>${r.trades}</td></tr>`).join("")}<tr><td>Buy &amp; Hold</td><td>${fmt(bh.ret*100,1)}%</td><td>${fmt(bh.sharpe,2)}</td><td>${fmt(bh.drawdown*100,1)}%</td><td>1</td></tr></tbody></table></div>`;const edge=(result.ret-result.baseline.ret)*100;setConclusion("#tabularInsight",`${$("#tabularTicker").value}, ${algo}: доходность ${fmt(result.ret*100,1)}%, Sharpe ${fmt(result.sharpe,2)}, max drawdown ${fmt(result.drawdown*100,1)}%; относительно Buy & Hold ${edge>=0?"+":""}${fmt(edge,1)} п.п. Лучший Sharpe в общем сравнении: ${best[0]} (${fmt(best[1].sharpe,2)}).`,edge>=0?"good":"warn");evaluatePrediction("tabular",`лучший Sharpe: ${best[0]} (${fmt(best[1].sharpe,2)}).`);}
function resetTabular(){tabularProtocol=[];$("#tabularActionLog").innerHTML="";$("#tabularComparison").innerHTML="";chart($("#tabularChart"),[{data:[100000,100000],color:"#62e4ff"}],{min:99000,max:101000,decimals:0});setConclusion("#tabularInsight","Параметры сброшены. Зафиксируйте гипотезу и запустите обучение.");$("#tabularAction").textContent="READY";}
function windowRows(all,scenario){if(scenario==="standard")return all.filter(r=>r.date.startsWith("2025-"));if(scenario==="recent")return all.slice(-180);let best=all.slice(-120),worst=Infinity;for(let i=0;i<=all.length-120;i+=5){const w=all.slice(i,i+120),v=w.at(-1).close/w[0].close-1;if(v<worst){worst=v;best=w}}return best;}
function features(rows,i){const close=j=>rows[Math.max(0,j)].close,ret=n=>close(i)/close(i-n)-1;const r20=[];for(let k=Math.max(1,i-19);k<=i;k++)r20.push(close(k)/close(k-1)-1);const volumes=rows.slice(Math.max(0,i-20),i+1).map(x=>x.volume||0);return{r1:ret(1),mom5:ret(5),mom20:ret(20),vol:std(r20),volumeZ:(rows[i].volume-mean(volumes))/std(volumes)};}
function policyDecision(f,algo,risk){const normalized=f.mom20/(f.vol*Math.sqrt(20)+1e-6),short=f.mom5/(f.vol*Math.sqrt(5)+1e-6);let q=Math.tanh(.55*normalized+.25*short+.08*f.volumeZ);if(algo==="Double DQN")q=Math.tanh(q*.88+.12*Math.sign(f.r1)*Math.min(1,Math.abs(f.r1)/(f.vol+1e-6)));if(algo==="Dueling Double DQN"){const value=Math.tanh(.45*normalized-.35*risk*f.vol*10),adv=Math.tanh(.45*short+.1*f.volumeZ);q=value+adv-adv/2}const threshold=.08+.08*risk;return{q,position:q>threshold?1:0,label:q>threshold?"LONG":"CASH"};}
function evaluateTicker(rows,algo,fee,risk,scenario){const data=windowRows(rows,scenario),start=20,eq=[100000],bh=[100000],actions=[],position=0,trades=0;for(let i=start;i<data.length-1;i++){const f=features(data,i),decision=policyDecision(f,algo,risk),nextRet=data[i+1].close/data[i].close-1;let capital=eq.at(-1);if(decision.position!==position){capital*=1-fee;trades++}position=decision.position;capital*=1+position*nextRet;eq.push(capital);bh.push(bh.at(-1)*(1+nextRet));actions.push({date:data[i].date,action:decision.label,q:decision.q,ret:nextRet,equity:capital,features:f})}return{data:data.slice(start),eq,bh,actions,trades,...metrics(eq),baseline:metrics(bh)};}
function animateTrade(result){let i=0;const step=()=>{const a=result.actions[Math.min(i,result.actions.length-1)];if(!a)return;$("#tradeDate").textContent=`${a.date} · Q=${fmt(a.q,2)}`;$("#tradeActionBadge").textContent=a.action;$("#tradeActionBadge").className=`trade-action ${a.action.toLowerCase()}`;i+=Math.max(1,Math.ceil(result.actions.length/35));if(i<result.actions.length)requestAnimationFrame(step)};step();}
function renderTradeComparison(rows,fee,risk,scenario){const algos=["DQN","Double DQN","Dueling Double DQN"],results=algos.map(a=>[a,evaluateTicker(rows,a,fee,risk,scenario)]);const bh=results[0][1].baseline;$("#tradeComparison").innerHTML=`<h3>Сравнение на одном test-периоде</h3><div class="table-scroll"><table><thead><tr><th>Политика</th><th>Доходность</th><th>Sharpe</th><th>Max DD</th><th>Сделок</th></tr></thead><tbody>${results.map(([a,r])=>`<tr><td>${a}</td><td>${fmt(r.ret*100,1)}%</td><td>${fmt(r.sharpe,2)}</td><td>${fmt(r.drawdown*100,1)}%</td><td>${r.trades}</td></tr>`).join("")}<tr><td>Buy &amp; Hold</td><td>${fmt(bh.ret*100,1)}%</td><td>${fmt(bh.sharpe,2)}</td><td>${fmt(bh.drawdown*100,1)}%</td><td>1</td></tr></tbody></table></div>`;return results;}
function simulateTrading(){if(!moexData)return setConclusion("#tradeInsight","Данные MOEX ещё загружаются.","warn");const ticker=$("#tradeTicker").value,algo=$("#tradingAlgo").value,fee=+$("#fee").value/100,risk=+$("#risk").value,scenario=$("#tradeScenario").value,rows=moexData.securities[ticker].candles,result=evaluateTicker(rows,algo,fee,risk,scenario);tradeProtocol=result.actions;animateChart($("#tradeChart"),[{data:result.eq,color:"#62e4ff"},{data:result.bh,color:"#687893",dash:[7,6]}],{min:Math.min(...result.eq,...result.bh)*.98,max:Math.max(...result.eq,...result.bh)*1.02,decimals:0});animateTrade(result);$("#equityValue").textContent=new Intl.NumberFormat("ru-RU",{style:"currency",currency:"RUB",maximumFractionDigits:0}).format(result.eq.at(-1));$("#tradeReturn").textContent=`${result.ret>=0?"+":""}${fmt(result.ret*100,1)}%`;$("#tradeReturn").className=result.ret>=0?"positive":"negative";$("#tradeSharpe").textContent=fmt(result.sharpe,2);$("#tradeDrawdown").textContent=`−${fmt(result.drawdown*100,1)}%`;$("#tradeCount").textContent=result.trades;const edge=(result.ret-result.baseline.ret)*100,verdict=edge>=0?`выше Buy & Hold на ${fmt(edge,1)} п.п.`:`ниже Buy & Hold на ${fmt(Math.abs(edge),1)} п.п.`;setConclusion("#tradeInsight",`${ticker}, ${algo}: ${verdict}; Sharpe ${fmt(result.sharpe,2)}, просадка ${fmt(result.drawdown*100,1)}%. Сравнивайте алгоритмы только на одинаковом test-периоде.`,edge>=0?"good":"warn");$("#tradeActionLog").innerHTML="";result.actions.filter((_,i)=>i%Math.max(1,Math.floor(result.actions.length/6))===0).slice(0,6).forEach(a=>addAction("#tradeActionLog",`${a.date}: ${a.action}; Q=${fmt(a.q,2)}, momentum20=${fmt(a.features.mom20*100,1)}%, vol20=${fmt(a.features.vol*100,2)}%, капитал ₽${fmt(a.equity,0)}.`));const compared=renderTradeComparison(rows,fee,risk,scenario),best=compared.sort((a,b)=>b[1].sharpe-a[1].sharpe)[0];evaluatePrediction("trading",`Лучший Sharpe: ${best[0]} (${fmt(best[1].sharpe,2)}).`);}
function resetTrading(){tradeProtocol=[];$("#tradeActionLog").innerHTML="";$("#tradeComparison").innerHTML="";chart($("#tradeChart"),[{data:[100000,100000],color:"#62e4ff"}],{min:99000,max:101000,decimals:0});setConclusion("#tradeInsight","Параметры сброшены. Сформулируйте гипотезу и запустите test.");$("#tradeActionBadge").textContent="READY";$("#tradeDate").textContent="Test ещё не запущен";}

// Multi-agent portfolio on synchronized MOEX observations.
let marlState=null;
function selectedTickers(){return [...document.querySelectorAll('.ticker-picker input:checked')].map(x=>x.value);}
function alignedPortfolioRows(tickers){const maps=tickers.map(t=>new Map(moexData.securities[t].candles.filter(r=>r.date.startsWith("2025-")).map(r=>[r.date,r]))),dates=[...maps[0].keys()].filter(d=>maps.every(m=>m.has(d)));return dates.map(d=>({date:d,prices:tickers.map((_,i)=>maps[i].get(d).close)}));}
function softmax(xs){const m=Math.max(...xs),e=xs.map(x=>Math.exp(clamp(x-m,-12,12))),s=e.reduce((a,b)=>a+b,0);return e.map(x=>x/s);}
function portfolioSignals(index){const p=marlState.rows,i=Math.max(20,index),moms=marlState.tickers.map((_,j)=>p[i].prices[j]/p[i-20].prices[j]-1),vols=marlState.tickers.map((_,j)=>std(Array.from({length:20},(_,k)=>p[i-k].prices[j]/p[i-k-1].prices[j]-1))),market=clamp(mean(moms)/(mean(vols)*Math.sqrt(20)+1e-6),-1,1),riskSignal=clamp(-mean(vols)*18,-1,0),scores=moms.map((m,j)=>m/(vols[j]*Math.sqrt(20)+1e-6));let raw;if($("#coopMode").value==="ctde")raw=softmax(scores.map((s,j)=>.7*s-.3*vols[j]*30));else if($("#coopMode").value==="independent")raw=softmax(scores.map(s=>s*.55));else{const ranked=[...scores].sort((a,b)=>a-b);raw=softmax(scores.map(s=>ranked.indexOf(s)-scores.length/2))}const cap=+$("#position").value/100;let weights=raw.map(w=>Math.min(w*.9,cap));let sum=weights.reduce((a,b)=>a+b,0);if(sum>.9)weights=weights.map(w=>w*.9/sum);const cash=1-weights.reduce((a,b)=>a+b,0),diversification=1-weights.reduce((a,b)=>a+b*b,0);return{market,risk:riskSignal,allocation:clamp(diversification,-1,1),weights,cash,moms,vols};}
function resetMarl(){if(!moexData)return;const tickers=selectedTickers();if(tickers.length<3||tickers.length>6){setConclusion("#marlInsight","Выберите от трёх до шести компаний.","warn");return}marlState={tickers,rows:alignedPortfolioRows(tickers),index:20,weights:Array(tickers.length).fill(0),cash:1,equity:[100000],baseline:[100000],turnover:0};marlProtocol=[];$("#marlActionLog").innerHTML="";renderPortfolioWeights(marlState.weights,marlState.cash);chart($("#marlChart"),[{data:[100000,100000],color:"#62e4ff"},{data:[100000,100000],color:"#687893",dash:[7,6]}],{min:99000,max:101000,decimals:0});setConclusion("#marlInsight","Портфель сброшен. Выполните первую ребалансировку.");}
function renderPortfolioWeights(weights,cash){const colors=["#62e4ff","#4f7cff","#b9f36b","#ffbd59","#ff6e83","#9b8cff"];$("#portfolioWeights").innerHTML=marlState.tickers.map((t,i)=>`<div style="--weight:${weights[i]*100}%;--asset:${colors[i]}"><span>${t}</span><b>${fmt(weights[i]*100,1)}%</b></div>`).join("")+`<div style="--weight:${cash*100}%;--asset:#687893"><span>CASH</span><b>${fmt(cash*100,1)}%</b></div>`;}
function updateMarlMetrics(sig,label){const m=metrics(marlState.equity),turn=marlState.turnover*100;$("#marlReturn").textContent=`${m.ret>=0?"+":""}${fmt(m.ret*100,1)}%`;$("#marlSharpe").textContent=fmt(m.sharpe,2);$("#marlDrawdown").textContent=`−${fmt(m.drawdown*100,1)}%`;$("#marlTurnover").textContent=`${fmt(turn,1)}%`;[["market",sig.market],["risk",sig.risk],["news",sig.allocation]].forEach(([id,v])=>{$(`#${id}Meter`).value=v;$(`#${id}Signal`).textContent=`${v>=0?"+":""}${fmt(v,2)}`});$("#marlDecision").textContent=label;$("#marlConfidence").textContent=`доля cash ${fmt(sig.cash*100,0)}%`;renderPortfolioWeights(sig.weights,sig.cash);chart($("#marlChart"),[{data:marlState.equity,color:"#62e4ff"},{data:marlState.baseline,color:"#687893",dash:[7,6]}],{min:Math.min(...marlState.equity,...marlState.baseline)*.98,max:Math.max(...marlState.equity,...marlState.baseline)*1.02,decimals:0});}
function marlStep(silent=false){if(!moexData)return;if(!marlState)resetMarl();if(!marlState||marlState.index>=marlState.rows.length-1)return;const period=+$("#rebalancePeriod").value,start=marlState.index,end=Math.min(start+period,marlState.rows.length-1),sig=portfolioSignals(start),prevWeights=marlState.weights,turnover=sig.weights.reduce((s,w,i)=>s+Math.abs(w-prevWeights[i]),0)+Math.abs(sig.cash-marlState.cash);marlState.turnover+=turnover;let equity=marlState.equity.at(-1),base=marlState.baseline.at(-1);for(let d=start+1;d<=end;d++){const dayR=marlState.tickers.map((_,j)=>marlState.rows[d].prices[j]/marlState.rows[d-1].prices[j]-1);equity*=1+sig.weights.reduce((s,w,j)=>s+w*dayR[j],0);base*=1+mean(dayR);marlState.equity.push(equity);marlState.baseline.push(base)}marlState.weights=sig.weights;marlState.cash=sig.cash;marlState.index=end;const top=sig.weights.indexOf(Math.max(...sig.weights)),label=turnover>.25?"REBALANCE":"HOLD",date=marlState.rows[start].date,entry={date,action:label,equity,turnover,weights:Object.fromEntries(marlState.tickers.map((t,i)=>[t,sig.weights[i]])),cash:sig.cash,market:sig.market,risk:sig.risk,diversification:sig.allocation};marlProtocol.push(entry);updateMarlMetrics(sig,label);const reason=`${date}: ${label}; максимум ${marlState.tickers[top]} ${fmt(sig.weights[top]*100,1)}%, cash ${fmt(sig.cash*100,1)}%, turnover ${fmt(turnover*100,1)}%.`;$("#newsTicker").textContent=reason;if(!silent){setConclusion("#marlInsight",`Market Agent оценил режим ${fmt(sig.market,2)}, Risk Agent ${fmt(sig.risk,2)}, Allocation Agent ${fmt(sig.allocation,2)}. ${reason}`,sig.risk<-.5?"warn":"good");addAction("#marlActionLog",reason)}return marlState.index>=marlState.rows.length-1;}
function runMarl(){if(!marlState)resetMarl();if(!marlState)return;while(!marlStep(true)){};marlProtocol.slice(-6).reverse().forEach(x=>addAction("#marlActionLog",`${x.date}: ${x.action}; капитал ₽${fmt(x.equity,0)}, turnover ${fmt(x.turnover*100,1)}%.`));const m=metrics(marlState.equity),b=metrics(marlState.baseline),edge=(m.ret-b.ret)*100;setConclusion("#marlInsight",`Test завершён: MARL ${fmt(m.ret*100,1)}% против равновзвешенного ${fmt(b.ret*100,1)}%; разница ${edge>=0?"+":""}${fmt(edge,1)} п.п., Sharpe ${fmt(m.sharpe,2)}, max drawdown ${fmt(m.drawdown*100,1)}%.`,edge>=0?"good":"warn");evaluatePrediction("marl",`MARL ${fmt(m.ret*100,1)}%, baseline ${fmt(b.ret*100,1)}%, max drawdown ${fmt(m.drawdown*100,1)}%.`);}

const snippets={
  "rl-loop":{title:"Контракт среды Gymnasium",explain:"Среда отделена от алгоритма: reset() создаёт эпизод, step(action) возвращает наблюдение, награду и два разных признака завершения.",file:"python/cem_dog_bone/env.py",code:`obs, info = env.reset(seed=42)\nfor t in range(horizon):\n    action = agent.act(obs)\n    next_obs, reward, terminated, truncated, info = env.step(action)\n    agent.observe(obs, action, reward, next_obs, terminated)\n    obs = next_obs\n    if terminated or truncated:\n        break`},
  bandit:{title:"ε-greedy агент",explain:"Оценка Q(a) обновляется онлайн как выборочное среднее. ε управляет долей исследовательских действий.",file:"python/bandit/agents.py",code:`def select_action(self):\n    if self.rng.random() < self.epsilon:\n        return self.rng.integers(self.n_arms)\n    return int(np.argmax(self.q))\n\ndef update(self, action, reward):\n    self.n[action] += 1\n    self.q[action] += (reward - self.q[action]) / self.n[action]`},
  cem:{title:"Итерация Cross-Entropy Method",explain:"Обучаем политику не на всех действиях, а на парах «состояние—действие» из эпизодов выше квантильного порога.",file:"python/cem_dog_bone/train.py",code:`sessions = [generate_session(env, policy) for _ in range(batch_size)]\nthreshold = np.percentile([s.reward for s in sessions], percentile)\nelite = [s for s in sessions if s.reward >= threshold]\n\nX = np.concatenate([s.states for s in elite])\ny = np.concatenate([s.actions for s in elite])\npolicy.fit(X, y)`},
  tabular:{title:"Q-learning, SARSA и Expected SARSA",explain:"Методы отличаются TD-целью: жадное, фактически выбранное или ожидаемое следующее действие.",file:"python/tabular/agents.py",code:`if algorithm == "q_learning":\n    bootstrap = np.max(Q[next_state])\nelif algorithm == "sarsa":\n    bootstrap = Q[next_state, next_action]\nelse:\n    bootstrap = np.dot(epsilon_greedy_probs(Q[next_state]), Q[next_state])\nQ[state, action] += alpha * (reward + gamma * bootstrap - Q[state, action])`},
  trading:{title:"Dueling Double DQN",explain:"Online-сеть выбирает действие; target-сеть оценивает. Dueling-head разделяет ценность состояния V и относительные преимущества действий A.",file:"python/trading/agent.py",code:`with torch.no_grad():\n    next_action = online(next_state).argmax(1, keepdim=True)\n    next_q = target(next_state).gather(1, next_action)\n    td_target = reward + gamma * (1 - done) * next_q\n\nq = online(state).gather(1, action)\nloss = F.smooth_l1_loss(q, td_target)`},
  marl:{title:"Три агента и координатор",explain:"Market, Risk и Allocation Agent публикуют типизированные предложения. Координатор агрегирует их и проецирует веса на ограничения риска.",file:"python/marl/coordinator.py",code:`proposals = {\n  "market": market_agent.act(observation),\n  "risk": risk_agent.act(observation),\n  "allocation": allocation_agent.act(observation),\n}\nscore = sum(p.signal * p.confidence * weights[name]\n            for name, p in proposals.items())\ntarget = project_weights(score, position_limit, turnover_limit)`}
};
function openCode(key){const s=snippets[key],dlg=$("#codeDialog");$("#codeTitle").textContent=s.title;$("#codeExplain").textContent=s.explain;$("#codeContent").textContent=s.code;$("#codeFileLink").href=`https://github.com/PetrNikitin20/RL_education/blob/main/${s.file}`;dlg.showModal()}

const predictions={};
function bindPredictions(){document.querySelectorAll(".prediction-card").forEach(card=>{const key=card.dataset.prediction,select=card.querySelector("select"),button=card.querySelector("button"),out=card.querySelector("output");button.onclick=()=>{if(!select.value){out.textContent="Сначала выберите гипотезу.";return}predictions[key]=select.value;select.disabled=true;button.disabled=true;out.textContent=`Зафиксировано: ${select.value}. После test сравните ожидание с результатом.`;card.classList.add("locked")}})}
function evaluatePrediction(key,result){const card=document.querySelector(`[data-prediction="${key}"]`);if(!card)return;const hypothesis=predictions[key],out=card.querySelector("output");out.textContent=hypothesis?`Гипотеза «${hypothesis}». Результат: ${result} Объясните совпадение или расхождение.`:`Результат: ${result} В следующий раз зафиксируйте гипотезу до запуска.`;}
