function safeStored(key,fallback=[]){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function downloadText(name,textValue,type="application/json"){const blob=new Blob([textValue],{type:`${type};charset=utf-8`}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function renderJournalRows(container,entries){container.innerHTML="";if(!entries.length){container.textContent="Записей пока нет. Сохраните первый проверяемый эксперимент.";return}const table=document.createElement("table"),head=document.createElement("thead"),body=document.createElement("tbody"),hr=document.createElement("tr");["Дата","Модель и версия","Источник","Тип результата","Метрики"].forEach(x=>{const th=document.createElement("th");th.textContent=x;hr.append(th)});head.append(hr);entries.slice().reverse().forEach(entry=>{const row=document.createElement("tr");[entry.date,`${entry.model} ${entry.version}`.trim(),entry.source,entry.resultType,entry.metrics].forEach(x=>{const td=document.createElement("td");td.textContent=x;row.append(td)});body.append(row)});table.append(head,body);container.append(table)}
function injectAiLabBlocks(){document.querySelectorAll(".lab").forEach(lab=>{const cfg=aiLabBank[lab.id];if(!cfg)return;const key=`rl-ai-journal-${lab.id}`,section=document.createElement("section");section.className="ai-lab-block";section.innerHTML=`<div class="ai-block-heading"><div><span>Роль ИИ в выполнении работы</span><h3>Помощник по гипотезе, а не автор результата</h3></div><div class="evidence-tags"><b>${cfg.data}</b><b>${cfg.result}</b><b>Ответ ИИ требует проверки</b></div></div><div class="prompt-compare"><article class="prompt-bad"><span>Плохой промпт</span><p>${cfg.bad}</p><small>Нет условий, критерия проверки и запрета на выдумывание данных.</small></article><article class="prompt-good"><span>Хороший промпт</span><p>${cfg.good}</p><button class="mini-button copy-prompt" type="button">Скопировать промпт</button></article></div><div class="verification-pair"><article><span>Черновой ответ ИИ</span><p>${cfg.answer}</p></article><article><span>Проверка студентом</span><p>${cfg.check}</p><div class="verdict-buttons"><button type="button" data-verdict="Подтверждено">Подтверждено</button><button type="button" data-verdict="Отклонено">Отклонено</button><button type="button" data-verdict="Нужна проверка">Нужна проверка</button></div><output class="verdict-output">Вердикт ещё не зафиксирован.</output></article></div><details class="journal-panel"><summary>Журнал эксперимента · модель, промпт, данные, параметры и метрики</summary><form class="journal-form"><label>Модель ИИ<select name="model" required><option>ChatGPT</option><option>GigaChat</option><option>YandexGPT</option><option>Другая модель</option><option>Без внешней модели</option></select></label><label>Версия или дата доступа<input name="version" required placeholder="например, 2026-09-24"></label><label>Дата эксперимента<input name="date" type="date" required></label><label class="wide-field">Параметры<textarea name="params" required placeholder="алгоритм, seed, гиперпараметры, версия кода"></textarea></label><label class="wide-field">Промпт<textarea name="prompt" required placeholder="без ФИО, оценок и закрытых материалов"></textarea></label><label class="wide-field">Источник данных<input name="source" required placeholder="ссылка, дата среза, лицензия"></label><label>Тип результата<select name="resultType" required><option>Реальный эксперимент</option><option>Демонстрационный результат</option><option>Синтетическое значение</option></select></label><label>Метрики<input name="metrics" required placeholder="например, Sharpe 0,82; Max DD 12%"></label><div class="journal-actions wide-field"><button class="button primary" type="submit">Сохранить запись</button><button class="button secondary export-journal" type="button">Экспорт JSON</button></div><p class="privacy-note wide-field">Не вводите персональные данные и оценки студентов. Журнал хранится только в браузере на этом устройстве.</p></form><output class="journal-status" aria-live="polite"></output><div class="journal-table table-scroll"></div></details>`;const hub=lab.querySelector(".resource-panel");(hub||lab.querySelector(".lab-brief"))?.insertAdjacentElement("afterend",section);const promptButton=section.querySelector(".copy-prompt");promptButton.onclick=async()=>{try{await navigator.clipboard.writeText(cfg.good);promptButton.textContent="Скопировано"}catch{promptButton.textContent="Выделите текст вручную"}};section.querySelectorAll("[data-verdict]").forEach(button=>button.onclick=()=>{section.querySelectorAll("[data-verdict]").forEach(x=>x.classList.remove("active"));button.classList.add("active");section.querySelector(".verdict-output").textContent=`Вердикт: ${button.dataset.verdict}. Добавьте обоснование в журнал эксперимента.`;localStorage.setItem(`${key}-verdict`,button.dataset.verdict)});const previousVerdict=localStorage.getItem(`${key}-verdict`);if(previousVerdict){const button=section.querySelector(`[data-verdict="${previousVerdict}"]`);button?.classList.add("active");section.querySelector(".verdict-output").textContent=`Вердикт: ${previousVerdict}.`};const form=section.querySelector(".journal-form"),dateInput=form.elements.date;dateInput.value=new Date().toISOString().slice(0,10);form.elements.prompt.value=cfg.good;form.elements.source.value=cfg.data;const entries=safeStored(key);renderJournalRows(section.querySelector(".journal-table"),entries);form.onsubmit=event=>{event.preventDefault();const entry=Object.fromEntries(new FormData(form));entry.savedAt=new Date().toISOString();entries.push(entry);localStorage.setItem(key,JSON.stringify(entries));renderJournalRows(section.querySelector(".journal-table"),entries);section.querySelector(".journal-status").textContent=`Запись сохранена. Всего записей: ${entries.length}.`;form.elements.metrics.value=""};section.querySelector(".export-journal").onclick=()=>downloadText(`RL_${lab.id}_ai_journal.json`,JSON.stringify(entries,null,2))})}

