  {q:"ИИ предложил ссылку на статью. Что делать первым?",a:["Открыть первоисточник и проверить авторов, содержание и вывод","Сразу включить ссылку в обзор","Попросить ИИ подтвердить собственный ответ"],correct:0},
  {q:"Какие данные нельзя отправлять во внешнюю модель?",a:["Персональные данные, оценки и закрытые работы","Публичную ссылку на MOEX ISS","Обезличенные параметры эксперимента"],correct:0},
  {q:"Кому принадлежит итоговый исследовательский вывод?",a:["Студенту, который проверил источники и эксперимент","ИИ-модели","Тому, кто написал самый длинный промпт"],correct:0}
