function injectEntryTest(){const mount=$("#entryTest");if(!mount)return;let index=0,score=0;const render=()=>{const q=entryQuiz[index];mount.innerHTML=`<div class="entry-progress">Вопрос ${index+1} из ${entryQuiz.length}</div><p>${q.q}</p><div class="quiz-options">${q.a.map((x,i)=>`<button type="button" data-entry-answer="${i}">${x}</button>`).join("")}</div><output aria-live="polite">Выберите ответ.</output>`;mount.querySelectorAll("[data-entry-answer]").forEach(button=>button.onclick=()=>{const chosen=+button.dataset.entryAnswer,ok=chosen===q.correct;if(ok)score++;mount.querySelectorAll("[data-entry-answer]").forEach((option,i)=>{option.disabled=true;if(i===q.correct)option.classList.add("correct");else if(i===chosen)option.classList.add("wrong")});mount.querySelector("output").textContent=ok?"Верно. Переходим дальше.":"Неверно. В исследовании проверяем источник, данные и собственный вывод.";const next=document.createElement("button");next.className="mini-button";next.textContent=index===entryQuiz.length-1?"Показать результат":"Следующий вопрос";next.onclick=()=>{index++;if(index<entryQuiz.length)render();else{const percent=Math.round(score/entryQuiz.length*100);localStorage.setItem("rl-entry-score",String(percent));mount.innerHTML=`<div class="entry-result"><strong>${score} из ${entryQuiz.length} · ${percent}%</strong><p>${percent===100?"Готовность высокая: переходите к лабораторным работам.":"Перед экспериментом изучите правила и повторите диагностику."}</p><button class="mini-button" type="button">Повторить</button></div>`;mount.querySelector("button").onclick=()=>{index=0;score=0;render()}}};mount.append(next)})};render()}

